import * as React from 'react'

/** Where a sliding indicator should sit, along one axis, in container pixels. */
export interface SlidingIndicator {
  /** Distance from the container's start edge (left for `x`, top for `y`). */
  offset: number
  /** Length along the axis (width for `x`, height for `y`). */
  size: number
}

export interface SlidingIndicatorOptions {
  /** Axis the indicator travels along. */
  axis?: 'x' | 'y'
  /** Attribute carrying each item's id on its element. */
  attribute?: string
  /** Re-measure when this changes (item count, labels, anything that reflows). */
  changeKey?: unknown
}

/**
 * Measures the active item inside a container so a single element can animate
 * between items instead of the highlight jumping.
 *
 * Returns null until a measurement lands, so a caller renders no indicator on
 * the first paint rather than one at zero.
 *
 * Shared by `TabBar` (underline), `SegmentedControl` (fill pill) and
 * `SidebarTabs` (highlight) -- the three had no reason to travel at different
 * speeds or fail differently on the edge case below.
 *
 * Offsets are physical (`offsetLeft`/`offsetTop`), so a caller positions with
 * physical `left`/`top` and both directions agree without an RTL branch.
 */
export function useSlidingIndicator(
  containerRef: React.RefObject<HTMLElement | null>,
  activeId: string | null | undefined,
  { axis = 'x', attribute = 'data-tab-id', changeKey }: SlidingIndicatorOptions = {},
): SlidingIndicator | null {
  const [indicator, setIndicator] = React.useState<SlidingIndicator | null>(null)

  const measure = React.useCallback(() => {
    const container = containerRef.current
    if (!container || !activeId) {
      setIndicator(null)
      return
    }
    const el = container.querySelector<HTMLElement>(`[${attribute}="${activeId}"]`)
    // A hidden container (display:none at another breakpoint -- the sidebar
    // layout taking over from the tab bar) measures 0. Keep the last good
    // numbers instead of collapsing, so the indicator comes back intact; the
    // ResizeObserver re-measures on the 0 -> visible transition.
    const size = axis === 'x' ? el?.offsetWidth : el?.offsetHeight
    if (!el || !size) return
    setIndicator({ offset: axis === 'x' ? el.offsetLeft : el.offsetTop, size })
  }, [containerRef, activeId, axis, attribute])

  React.useEffect(() => {
    measure()
  }, [measure, changeKey])

  React.useEffect(() => {
    const el = containerRef.current
    if (!el || typeof ResizeObserver === 'undefined') return
    const ro = new ResizeObserver(() => measure())
    ro.observe(el)
    return () => ro.disconnect()
  }, [containerRef, measure])

  return indicator
}
